/**
 * Category Filtering Utility for Customer Storefront
 * Filters out test artifact categories generated by verification scripts
 * without deleting database records.
 */

export const isLegitCategory = (category) => {
  if (!category || !category.name) return false;
  const name = category.name.trim();

  // Exclude test script artifacts (e.g., "Verify Category 179...", "Sports Gear Updated 179...", timestamp suffix)
  if (/^Verify Category/i.test(name)) return false;
  if (/^Sports Gear Updated/i.test(name)) return false;
  if (/^Order Test/i.test(name)) return false;
  if (/\d{10,}/.test(name)) return false;

  return true;
};

export const filterLegitCategories = (categories = []) => {
  if (!Array.isArray(categories)) return [];
  return categories.filter(isLegitCategory);
};
